/* SPU virtual local store size. Moved up from its old spot near
 * spu_thread_get_or_alloc_ls so sys_spu_thread_initialize_handler (below) and
 * the SPU ELF cache can both see it. */
#define SPU_LS_SIZE  (256 * 1024)

/* Host-side cache of full SPU ELF images, keyed by the guest sys_spu_image
 * EA used at sys_spu_image_open time. image_open runs before any thread (and
 * thus any LS) exists, so we stash the whole file here and copy its PT_LOAD
 * segments into the thread LS at sys_spu_thread_initialize. Bounded, leak-safe
 * (re-opening the same img_ea frees the previous buffer). Defined here (not
 * near :714) because sys_spu_thread_initialize_handler below uses it. */
#define SPU_IMAGE_CACHE_MAX 64
typedef struct { uint32_t img_ea; uint8_t* bytes; size_t len; } spu_image_cache_t;
static spu_image_cache_t s_spu_image_cache[SPU_IMAGE_CACHE_MAX];

static void spu_image_cache_store(uint32_t img_ea, uint8_t* bytes, size_t len)
{
    if (!img_ea) { free(bytes); return; }
    int free_slot = -1;
    for (int i = 0; i < SPU_IMAGE_CACHE_MAX; i++) {
        if (s_spu_image_cache[i].img_ea == img_ea) {  /* replace */
            free(s_spu_image_cache[i].bytes);
            s_spu_image_cache[i].bytes = bytes;
            s_spu_image_cache[i].len   = len;
            return;
        }
        if (free_slot < 0 && s_spu_image_cache[i].bytes == NULL)
            free_slot = i;
    }
    if (free_slot < 0) { free(bytes); return; }  /* full: drop, stay non-breaking */
    s_spu_image_cache[free_slot].img_ea = img_ea;
    s_spu_image_cache[free_slot].bytes  = bytes;
    s_spu_image_cache[free_slot].len    = len;
}

static const spu_image_cache_t* spu_image_cache_find(uint32_t img_ea)
{
    if (!img_ea) return NULL;
    for (int i = 0; i < SPU_IMAGE_CACHE_MAX; i++)
        if (s_spu_image_cache[i].img_ea == img_ea && s_spu_image_cache[i].bytes)
            return &s_spu_image_cache[i];
    return NULL;
}

