/*
 * Pure SPU ELF32 (big-endian, EM_SPU) PT_LOAD loader.
 * Parses an in-memory SPU ELF and copies each PT_LOAD segment into a 256 KB
 * SPU local store image at its p_vaddr (p_filesz bytes), then zeroes the
 * p_memsz - p_filesz BSS tail. No host I/O, no globals: callable from tests.
 */
#ifndef PS3RECOMP_SPU_ELF_H
#define PS3RECOMP_SPU_ELF_H

#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Returns the number of PT_LOAD segments copied into `ls` (>0 success),
 * 0 if `elf` is not a usable 32-bit big-endian EM_SPU ELF (caller falls
 * back to legacy behaviour), or -1 on a structurally malformed ELF.
 * On success, *out_entry (if non-NULL) receives the ELF e_entry.
 * Segments whose [p_vaddr, p_vaddr+p_memsz) fall outside [0, ls_size) are
 * skipped (not fatal). */
int spu_load_elf32_into_ls(const uint8_t* elf, size_t elf_len,
                           uint8_t* ls, size_t ls_size, uint32_t* out_entry);

#ifdef __cplusplus
}
#endif

#endif /* PS3RECOMP_SPU_ELF_H */


