/*
 * Pure SPU ELF32 BE / EM_SPU PT_LOAD loader. See spu_elf.h.
 * Field offsets verified vs tools/wrap_spu_elf.py:
 *   EHDR (52B): e_machine@18 u16, e_entry@24 u32, e_phoff@28 u32,
 *               e_phentsize@42 u16, e_phnum@44 u16.
 *   PHDR (>=32B): p_type@0, p_offset@4, p_vaddr@8, p_filesz@16, p_memsz@20 (BE u32).
 */
#include "spu_elf.h"
#include <string.h>

#define EM_SPU      23
#define PT_LOAD     1
#define EHDR_SIZE   52u
#define PHDR_SIZE   32u

static uint16_t rd_be16(const uint8_t* p)
{
    return (uint16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}
static uint32_t rd_be32(const uint8_t* p)
{
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] <<  8) | (uint32_t)p[3];
}

int spu_load_elf32_into_ls(const uint8_t* elf, size_t elf_len,
                           uint8_t* ls, size_t ls_size, uint32_t* out_entry)
{
    if (!elf || !ls || elf_len < EHDR_SIZE) return 0;
    if (!(elf[0] == 0x7F && elf[1] == 'E' && elf[2] == 'L' && elf[3] == 'F'))
        return 0;
    if (elf[4] != 1 || elf[5] != 2) return 0;          /* ELFCLASS32, ELFDATA2MSB */
    if (rd_be16(elf + 18) != EM_SPU) return 0;

    uint32_t e_entry     = rd_be32(elf + 24);
    uint32_t e_phoff     = rd_be32(elf + 28);
    uint16_t e_phentsize = rd_be16(elf + 42);
    uint16_t e_phnum     = rd_be16(elf + 44);

    if (e_phoff == 0 || e_phnum == 0) return 0;        /* nothing to load */
    if (e_phentsize < PHDR_SIZE) return -1;            /* malformed */
    if ((uint64_t)e_phoff + (uint64_t)e_phentsize * e_phnum > elf_len)
        return -1;

    int loaded = 0;
    for (uint16_t i = 0; i < e_phnum; i++) {
        const uint8_t* ph = elf + e_phoff + (size_t)i * e_phentsize;
        if (rd_be32(ph + 0) != PT_LOAD) continue;

        uint32_t p_offset = rd_be32(ph + 4);
        uint32_t p_vaddr  = rd_be32(ph + 8);
        uint32_t p_filesz = rd_be32(ph + 16);
        uint32_t p_memsz  = rd_be32(ph + 20);

        if (p_memsz == 0) continue;
        if ((uint64_t)p_vaddr + p_memsz > ls_size) continue;
        if (p_filesz > p_memsz) continue;
        if ((uint64_t)p_offset + p_filesz > elf_len) continue;

        if (p_filesz)
            memcpy(ls + p_vaddr, elf + p_offset, p_filesz);
        if (p_memsz > p_filesz)
            memset(ls + p_vaddr + p_filesz, 0, p_memsz - p_filesz);
        loaded++;
    }

    if (loaded > 0 && out_entry) *out_entry = e_entry;
    return loaded;
}

