/*
 * Standalone unit test for spu_load_elf32_into_ls (runtime/spu/spu_elf.c).
 * Builds a tiny BE EM_SPU ELF32 with one PT_LOAD (memsz>filesz => BSS tail),
 * loads into 256 KB LS, asserts bytes@p_vaddr, BSS zeroed, neighbors
 * untouched, count==1, entry match, plus truncated + wrong-machine rejects.
 * Depends ONLY on spu_elf.{c,h}. Uses the same byte layout wrap_spu_elf.py emits.
 *
 * Build (from runtime/spu/tests):
 *   gcc -std=c11 -Wall -Wextra -I.. test_spu_elf.c ../spu_elf.c -o test_spu_elf
 * Run:  ./test_spu_elf      (exit 0 = all passed)
 * Expected output (stderr):  [PASS] test_spu_elf -- 7 checks
 */
#include "../spu_elf.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define EM_SPU 23
#define PT_LOAD 1
#define EHDR_SIZE 52u
#define PHDR_SIZE 32u
#define LS_SIZE   (256u * 1024u)

static int g_fail = 0;
#define CHECK(cond, msg) do { if (!(cond)) { \
    fprintf(stderr, "FAIL: %s\n", msg); g_fail++; } } while (0)

static void put_be16(uint8_t* p, uint16_t v){ p[0]=(uint8_t)(v>>8); p[1]=(uint8_t)v; }
static void put_be32(uint8_t* p, uint32_t v){
    p[0]=(uint8_t)(v>>24); p[1]=(uint8_t)(v>>16);
    p[2]=(uint8_t)(v>>8);  p[3]=(uint8_t)v;
}

int main(void)
{
    const uint32_t code_off = EHDR_SIZE + PHDR_SIZE;        /* 84 */
    const uint32_t p_vaddr  = 0x400;
    const uint32_t e_entry  = 0x418;
    const uint8_t  code[]   = { 0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,
                                0xDE,0xAD,0xBE,0xEF };
    const uint32_t p_filesz = (uint32_t)sizeof(code);       /* 12 */
    const uint32_t p_memsz  = p_filesz + 16;                /* +16 BSS tail */

    size_t elf_len = code_off + p_filesz;
    uint8_t* elf = (uint8_t*)calloc(1, elf_len);

    elf[0]=0x7F; elf[1]='E'; elf[2]='L'; elf[3]='F';
    elf[4]=1;  /* ELFCLASS32 */
    elf[5]=2;  /* ELFDATA2MSB */
    elf[6]=1;  /* EV_CURRENT */
    put_be16(elf+16, 2);          /* e_type ET_EXEC */
    put_be16(elf+18, EM_SPU);     /* e_machine */
    put_be32(elf+20, 1);          /* e_version */
    put_be32(elf+24, e_entry);    /* e_entry */
    put_be32(elf+28, EHDR_SIZE);  /* e_phoff */
    put_be32(elf+32, 0);          /* e_shoff */
    put_be32(elf+36, 0);          /* e_flags */
    put_be16(elf+40, (uint16_t)EHDR_SIZE);  /* e_ehsize */
    put_be16(elf+42, (uint16_t)PHDR_SIZE);  /* e_phentsize */
    put_be16(elf+44, 1);                    /* e_phnum */
    put_be16(elf+46, 0);                    /* e_shentsize */
    put_be16(elf+48, 0);                    /* e_shnum */
    put_be16(elf+50, 0);                    /* e_shstrndx */

    uint8_t* ph = elf + EHDR_SIZE;
    put_be32(ph+0,  PT_LOAD);
    put_be32(ph+4,  code_off);   /* p_offset */
    put_be32(ph+8,  p_vaddr);    /* p_vaddr */
    put_be32(ph+12, p_vaddr);    /* p_paddr */
    put_be32(ph+16, p_filesz);   /* p_filesz */
    put_be32(ph+20, p_memsz);    /* p_memsz */
    put_be32(ph+24, 5);          /* p_flags PF_R|PF_X */
    put_be32(ph+28, 16);         /* p_align */

    memcpy(elf + code_off, code, p_filesz);

    uint8_t* ls = (uint8_t*)malloc(LS_SIZE);
    memset(ls, 0xAA, LS_SIZE);

    uint32_t entry = 0;
    int n = spu_load_elf32_into_ls(elf, elf_len, ls, LS_SIZE, &entry);

    CHECK(n == 1, "expected exactly 1 PT_LOAD copied");
    CHECK(entry == e_entry, "out_entry mismatch");
    CHECK(memcmp(ls + p_vaddr, code, p_filesz) == 0, "code bytes not at p_vaddr");
    int bss_ok = 1;
    for (uint32_t i = p_filesz; i < p_memsz; i++)
        if (ls[p_vaddr + i] != 0) bss_ok = 0;
    CHECK(bss_ok, "BSS tail not zeroed");
    CHECK(ls[p_vaddr - 1] == 0xAA && ls[p_vaddr + p_memsz] == 0xAA,
          "bytes outside segment were clobbered");

    uint32_t junk = 123;
    CHECK(spu_load_elf32_into_ls(elf, 10, ls, LS_SIZE, &junk) == 0,
          "truncated ELF should return 0");
    put_be16(elf+18, 0x0099);   /* wrong machine (overwrites both bytes 18,19) */
    CHECK(spu_load_elf32_into_ls(elf, elf_len, ls, LS_SIZE, &junk) == 0,
          "non-EM_SPU should return 0");
    put_be16(elf+18, EM_SPU);   /* restore (irrelevant; freed next) */

    free(ls); free(elf);
    if (g_fail) { fprintf(stderr, "[FAIL] test_spu_elf -- %d failed\n", g_fail); return 1; }
    fprintf(stderr, "[PASS] test_spu_elf -- 7 checks\n");
    return 0;
}

